-- Independent categories for tutorials and software.
CREATE TABLE IF NOT EXISTS content_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,section VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(191) NOT NULL,slug VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at BIGINT UNSIGNED NOT NULL,UNIQUE KEY uq_cc_section_slug(section,slug),KEY idx_cc_section(section,enabled,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
